@OptIn(ExperimentalCoroutinesApi::class) class InboxLinkDealTest {
    private fun fixture(n:String)=javaClass.classLoader!!.getResourceAsStream("fixtures/$n.json")!!.bufferedReader().use {it.readText()}
    private fun context(o:JSONObject)=InboxConversationFilesContext(o.getInt("business"),o.getInt("conversation"),o.getInt("epoch"),o.getInt("revision"))
    private fun deals()=APIDealReadRepository(FixtureDealReadTransport.fromJSON(fixture("deal-read")))
    private fun source()=APIInboxLinkDealRepository(FixtureInboxLinkDealReadTransport.fromJSON(fixture("inbox-link-deal")))
    private fun files()=APIInboxConversationFilesRepository(FixtureInboxConversationFilesTransport.fromJSON(fixture("inbox-conversation-files")))
    private suspend fun reference(c:InboxConversationFilesContext,id:Int=5701,raw:String="005701"):QualifiedDealReference {val s=DealReferenceSession();s.bind(c);s.show();s.update(raw,s.input);val t=s.begin(s.control)!!;s.accept(deals().deal(c.business,id),t);s.use(s.control);return s.state.choice!!}
    private suspend fun choose(p:DealReferenceModel,id:Int){p.clear(p.control);p.update("00$id",p.input);p.read(p.control);p.use(p.control)}
    private class Held(override val grants:List<SyntheticInboxLinkDealGrant>):SyntheticInboxLinkDealPort {val attempts=mutableListOf<InboxLinkDealAttempt>();val pending=mutableListOf<CompletableDeferred<SyntheticInboxLinkDealOutcome>>();override suspend fun execute(a:InboxLinkDealAttempt):SyntheticInboxLinkDealOutcome {attempts+=a;return withContext(NonCancellable){CompletableDeferred<SyntheticInboxLinkDealOutcome>().also {pending+=it}.await()}}}
    @Test fun genericThreeLinkSourceQualifiedScopeTwoGrantsConditionalReceiptBodyUnknown()=runTest {
        val d=JSONObject(fixture("inbox-link-deal"));val f=FixtureInboxLinkDealPort.fromJSON(fixture("inbox-link-deal"));val cases=d.getJSONArray("source_cases")
        for(i in 0 until cases.length()){val x=cases.getJSONObject(i);assertEquals(x.getString("name"),x.getBoolean("valid"),InboxLinkDealSource.decode(x.getString("response_json"),context(x.getJSONObject("context")))!=null)}
        val c=context(d.getJSONObject("context"));val s=InboxLinkDealSource.decode(d.getString("source_json"),c)!!;val scopes=d.getJSONArray("candidate_scope_cases")
        for(i in 0 until scopes.length()){val x=scopes.getJSONObject(i);val rc=context(x.getJSONObject("context"));val id=if(rc.business==101)5701 else 6701;assertEquals(x.getString("name"),x.getBoolean("valid"),InboxLinkDealCandidate.make(s,reference(rc,id,"00$id"))!=null)}
        suspend fun review(c:InboxConversationFilesContext,raw:String,id:Int=5701,input:String="005701"):InboxLinkDealReview {val original=InboxLinkDealSource.decode(raw,c)!!;return InboxLinkDealReview(original,f.grants.mapNotNull {it.authorization(c)}.first(),InboxLinkDealCandidate.make(original,reference(c,id,input))!!,1)}
        val receipts=d.getJSONArray("receipt_cases");for(i in 0 until receipts.length()){val x=receipts.getJSONObject(i);val r=review(context(x.getJSONObject("context")),x.getString("source_json"),x.getInt("deal_id"),x.getString("raw_input"));val l=InboxLinkDealLedger();assertEquals(x.getString("name"),x.getBoolean("valid"),InboxLinkDealReceipt.decode(x.getString("response_json"),l.begin(r)!!)!=null)}
        val matrix=d.getJSONArray("conditional_matrix");for(i in 0 until matrix.length()){val x=matrix.getJSONObject(i);val r=review(context(x.getJSONObject("context")),x.getString("source_json"),x.getInt("deal_id"),x.getString("raw_input"));val l=InboxLinkDealLedger();val receipt=InboxLinkDealReceipt.decode(x.getString("response_json"),l.begin(r)!!)!!;assertEquals(x.getInt("expected_client"),receipt.source.client);assertEquals(if(x.isNull("expected_lead"))null else x.getInt("expected_lead"),receipt.source.lead)}
        val r=review(c,d.getString("source_json"));val auth=r.authorization;val l=InboxLinkDealLedger();val a=l.begin(r)!!;val body=JSONObject(a.preparedBody());assertEquals(setOf("deal_id"),body.keys().asSequence().toSet());assertEquals(5701,body.getInt("deal_id"));assertEquals("/api/inbox/conversations/901/link-deal/",a.path);assertTrue(a.query.isEmpty());assertTrue(a.headers.isEmpty());assertNull(l.begin(r));assertFalse(l.acknowledge(auth,l.visible(auth)!!));l.complete(a,f.execute(a));val known=l.visible(auth)!!;assertEquals(InboxLinkDealPhase.RESPONSE,known.phase);assertEquals(5701,known.result!!.source.deal);assertEquals(701,known.result!!.source.client);assertEquals(81,known.result!!.source.lead);assertEquals(111,known.attempt.review.source.deal);assertTrue(l.acknowledge(auth,known))
        val u=l.begin(r)!!;l.complete(u,SyntheticInboxLinkDealOutcome.Unknown);val unknown=l.visible(auth)!!;val next=c.copy(epoch=2,revision=2);val matching=InboxLinkDealSource.decode(JSONObject().put("id",901).put("business",101).put("deal",5701).put("client",701).put("lead",81).put("updated_at","matching GET").toString(),next)!!;val na=f.grants[0].authorization(next)!!;assertEquals(unknown,l.visible(na));assertFalse(l.acknowledge(na,unknown));assertNull(l.begin(InboxLinkDealReview(matching,na,InboxLinkDealCandidate.make(matching,reference(next))!!,2)));assertEquals(u,l.records[1].attempt);assertEquals("005701",unknown.attempt.review.candidate.reference.rawInput)
        for(g in listOf(SyntheticInboxLinkDealGrant(101,901,5001,false,true),SyntheticInboxLinkDealGrant(101,901,5001,true,false),SyntheticInboxLinkDealGrant(101,902,5001,true,true),SyntheticInboxLinkDealGrant(101,901,0,true,true)))assertNull(g.authorization(c));assertNull(InboxLinkDealCandidate.make(s,reference(c).copy(readRevision=0)));assertNull(InboxLinkDealCandidate.make(s,reference(c).copy(rawInput="005702")))
        val other=SyntheticInboxLinkDealGrant(101,901,6002,true,true).authorization(next)!!;assertNull(l.visible(other));assertTrue(l.blocked(101,901));assertFalse(l.blocked(202,951))
    }
    private inner class Reads:InboxRepository {override suspend fun inbox(business:Int)=JsonContracts.inbox(fixture("inbox-$business"));override suspend fun thread(business:Int,id:Int)=JsonContracts.thread(fixture("inbox-$business-$id"))}
    @Test fun actualParentFrozenDealReferenceKnownUnknownMatchingReadAndBusinessABA()=runTest {
        Dispatchers.setMain(StandardTestDispatcher(testScheduler));val f=FixtureInboxLinkDealPort.fromJSON(fixture("inbox-link-deal"));val held=Held(f.grants);var matching=false;val get=FixtureInboxLinkDealReadTransport.fromJSON(fixture("inbox-link-deal"));val src=APIInboxLinkDealRepository(ReadTransport {q->if(matching && q.path=="/api/inbox/conversations/901/")ReadResponse(200,JSONObject().put("id",901).put("business",101).put("deal",5702).put("client",701).put("lead",81).put("updated_at","matching GET").toString())else get.get(q)})
        val m=InboxViewModel(Reads(),files=files(),deals=deals(),dealLinkRead=src,dealLinkSubmission=held)
        try {m.load(101,580);runCurrent();m.open(901);runCurrent();val original=m.state.thread;val container=m.fileMetadata!!;val link=container.linkDeal!!;val p=container.dealReference!!;m.openFiles(m.filesEntryControl);assertNull(link.source);assertEquals("",p.state.rawInput);link.load(link.control);val stale=link.control;p.update("005701",p.input);p.read(p.control);link.prepare(link.control);assertNull(link.review);p.use(p.control);link.prepare(stale);assertNull(link.review);assertTrue(link.canPrepare);link.prepare(link.control);val r=link.review;val frozen=p.state.choice;p.clearChoice(p.control);p.clear(p.control);p.update("005702",p.input);p.read(p.control);link.load(link.control);container.preparePriority(container.control);assertEquals(r,link.review);assertEquals(frozen,p.state.choice);assertTrue(link.canSubmit);assertNull(container.priorityReview);link.back(link.control);assertFalse(p.controlsBlocked());link.prepare(link.control);val control=link.control;val job=launch {link.submit(control)};runCurrent();val pending=link.record!!;link.submit(link.control);link.acknowledge(pending,link.control);assertEquals(1,held.attempts.size);assertTrue(m.conversationCommandsBlocked);assertTrue(p.controlsBlocked());m.closeFiles(m.filesPresentationControl);m.openFiles(m.filesEntryControl);held.pending[0].complete(f.execute(held.attempts[0]));job.join();val response=link.record!!;assertEquals(InboxLinkDealPhase.RESPONSE,response.phase);assertEquals(701,response.result!!.source.client);assertEquals(81,response.result!!.source.lead);assertEquals(5701,response.result!!.source.deal);assertEquals(original,m.state.thread);link.acknowledge(response,control);assertEquals(response,link.record);link.acknowledge(response,link.control);assertNull(link.source);assertNull(p.state.choice);assertEquals(1,link.retainedAttemptCount);assertFalse(m.conversationCommandsBlocked)
            link.load(link.control);choose(p,5702);link.prepare(link.control);val unknownJob=launch {link.submit(link.control)};runCurrent();held.pending[1].completeExceptionally(IllegalStateException("synthetic unknown"));unknownJob.join();val unknown=link.record!!;matching=true;link.load(link.control);link.acknowledge(unknown,link.control);choose(p,5701);link.prepare(link.control);assertEquals(InboxLinkDealPhase.UNKNOWN,unknown.phase);assertEquals(5702,unknown.attempt.review.candidate.reference.source.id);assertEquals(5702,link.source!!.deal);assertEquals(unknown,link.record);assertNull(link.review);assertFalse(link.canPrepare);m.closeFiles(m.filesPresentationControl);m.load(202,581);runCurrent();m.open(951);runCurrent();m.openFiles(m.filesEntryControl);assertEquals("",p.state.rawInput);assertNull(link.record);m.closeFiles(m.filesPresentationControl);m.load(101,582);runCurrent();m.open(901);runCurrent();m.openFiles(m.filesEntryControl);link.load(link.control);assertEquals(unknown,link.record);assertTrue(m.conversationCommandsBlocked)
        }finally{Dispatchers.resetMain()}
    }
    @Test fun nullAndAbsentDealLeadNoTwoGrantsCancellationAndLateOwner()=runTest {
        val f=FixtureInboxLinkDealPort.fromJSON(fixture("inbox-link-deal"));val a=InboxConversationFilesContext(101,901,583,1);val b=InboxConversationFilesContext(202,951,584,1)
        suspend fun ready(c:InboxConversationFilesContext,port:SyntheticInboxLinkDealPort,id:Int=5701):InboxLinkDealModel {val p=DealReferenceModel(deals());p.bind(c);p.show();val m=InboxLinkDealModel(source(),p,port);m.commandsBlocked={false};m.bind(c);m.show();m.load(m.control);choose(p,id);return m}
        for(id in listOf(5701,5702)){val m=ready(a.copy(conversation=902),f,id);m.prepare(m.control);m.submit(m.control);val receipt=m.record!!.result!!.source;assertEquals(if(id==5701)1701 else 1702,receipt.client);assertEquals(if(id==5701)3701 else null,receipt.lead);assertNull(m.record!!.attempt.review.source.client);assertNull(m.record!!.attempt.review.source.lead)}
        for(grants in listOf(emptyList(),listOf(SyntheticInboxLinkDealGrant(101,901,5001,false,true)),listOf(SyntheticInboxLinkDealGrant(101,901,5001,true,false)))){val m=ready(a,Held(grants));assertNotNull(m.picker!!.state.choice);m.prepare(m.control);assertNull(m.review);assertEquals(0,m.retainedAttemptCount)}
        val cp=Held(f.grants);val cancel=ready(a,cp);cancel.prepare(cancel.control);val cj=launch {cancel.submit(cancel.control)};runCurrent();cj.cancel();cp.pending[0].complete(f.execute(cp.attempts[0]));cj.join();assertEquals(InboxLinkDealPhase.UNKNOWN,cancel.record!!.phase);assertEquals(cp.attempts[0],cancel.record!!.attempt)
        val lp=Held(f.grants);val late=ready(a,lp);late.prepare(late.control);val lj=launch {late.submit(late.control)};runCurrent();late.hide();late.picker!!.bind(b);late.picker!!.show();late.bind(b);late.show();late.load(late.control);late.picker!!.update("006701",late.picker!!.input);val before=late.control;lp.pending[0].complete(f.execute(lp.attempts[0]));lj.join();assertEquals(before,late.control);assertEquals("006701",late.picker!!.state.rawInput);assertNull(late.record);assertEquals(1,late.retainedAttemptCount)
    }
    @Test fun dealAndBothOtherLinkCommandsShareUnknownBarrier()=runTest {
        val c=InboxConversationFilesContext(101,901,590,1);val f=FixtureInboxLinkDealPort.fromJSON(fixture("inbox-link-deal"));val clientFixture=FixtureInboxLinkClientPort.fromJSON(fixture("inbox-link-client"));val leadFixture=FixtureInboxLinkLeadPort.fromJSON(fixture("inbox-link-lead"));val held=Held(f.grants)
        val clientReads=object:ClientSearchRepository {override suspend fun searchClients(business:Int,search:String)=JsonContracts.clients(FixtureClientSearch.list(fixture("client-search-catalogue-$business"),business,search).body);override suspend fun clientProfile(business:Int,id:Int)=JsonContracts.clientProfile(FixtureClientSearch.profile(fixture("client-search-catalogue-$business"),business,id).body)}
        val leadReads=APILeadReadRepository(ReadTransport {FixtureLeadReadTransport.response(fixture("lead-read"),it)})
        fun container(clientPort:SyntheticInboxLinkClientPort=clientFixture,leadPort:SyntheticInboxLinkLeadPort=leadFixture,dealPort:SyntheticInboxLinkDealPort=held)=InboxConversationFilesModel(files(),linkRead=APIInboxLinkClientRepository(FixtureInboxLinkClientReadTransport.fromJSON(fixture("inbox-link-client"))),linkClients=clientReads,linkPort=clientPort,ownerScope=this,leads=leadReads,leadLinkRead=APIInboxLinkLeadRepository(FixtureInboxLinkLeadReadTransport.fromJSON(fixture("inbox-link-lead"))),leadLinkPort=leadPort,deals=deals(),dealLinkRead=source(),dealLinkPort=dealPort).also {it.commandsBlocked={false};it.bind(c);it.open(it.control)}
        val own=container();val link=own.linkDeal!!;link.load(link.control);choose(own.dealReference!!,5701);link.prepare(link.control);val job=launch {link.submit(link.control)};runCurrent();held.pending[0].complete(SyntheticInboxLinkDealOutcome.Unknown);job.join();val client=own.linkClient!!;client.load(client.control);client.open(client.control);assertFalse(client.canOpen);val lead=own.linkLead!!;lead.load(lead.control);val p=own.leadReference!!;p.search(p.control);p.open(3701,p.control);p.use(p.control);lead.prepare(lead.control);assertFalse(lead.canPrepare);assertNull(lead.review)
        val unknownClient=object:SyntheticInboxLinkClientPort {override val grants=clientFixture.grants;override suspend fun execute(a:InboxLinkClientAttempt)=SyntheticInboxLinkClientOutcome.Unknown};val fromClient=container(clientPort=unknownClient,dealPort=f);val cl=fromClient.linkClient!!;cl.load(cl.control);cl.open(cl.control);cl.search(cl.control,cl.picker!!.control);runCurrent();cl.openClient(1701,cl.control,cl.picker!!.control);runCurrent();cl.useClient(cl.control,cl.picker!!.control);cl.prepare(cl.control);cl.submit(cl.control);val dc=fromClient.linkDeal!!;dc.load(dc.control);choose(fromClient.dealReference!!,5701);dc.prepare(dc.control);assertFalse(dc.canPrepare);assertNull(dc.review)
        val unknownLead=object:SyntheticInboxLinkLeadPort {override val grants=leadFixture.grants;override suspend fun execute(a:InboxLinkLeadAttempt)=SyntheticInboxLinkLeadOutcome.Unknown};val fromLead=container(leadPort=unknownLead,dealPort=f);val ll=fromLead.linkLead!!;ll.load(ll.control);val pl=fromLead.leadReference!!;pl.search(pl.control);pl.open(3701,pl.control);pl.use(pl.control);ll.prepare(ll.control);ll.submit(ll.control);val dl=fromLead.linkDeal!!;dl.load(dl.control);choose(fromLead.dealReference!!,5701);dl.prepare(dl.control);assertFalse(dl.canPrepare);assertNull(dl.review);assertTrue(fromLead.blocksCommands(101,901))
    }
